import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.qUUbSc2K.js";var i=JSON.parse(`{"title":"Config API reference","description":"Generated API reference for @pikacss/config from exported surface and JSDoc.","frontmatter":{"title":"Config API reference","description":"Generated API reference for @pikacss/config from exported surface and JSDoc.","outline":[2,3],"relatedPackages":["@pikacss/config"],"relatedSources":["packages/config/src/host-load.ts","packages/config/src/host-scan.ts","packages/config/src/host-types.ts","packages/config/src/host.ts","packages/config/src/index.ts","packages/config/src/types.ts"],"category":"api","order":25},"headers":[],"relativePath":"api/config.md","filePath":"api/config.md"}`),a={name:`api/config.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /api/config.md for this page in Markdown format</div><h1 id="config-api-reference" tabindex="-1">Config API reference <a class="header-anchor" href="#config-api-reference" aria-label="Permalink to “Config API reference”">​</a></h1><details><summary>Source information</summary><ul><li>Package: <code>@pikacss/config</code></li><li>Generated from the exported surface and JSDoc in <code>packages/config/src/index.ts</code>.</li><li>Public entries: <code>@pikacss/config</code>, <code>@pikacss/config/host</code></li><li>Source files: <code>packages/config/src/host-load.ts</code>, <code>packages/config/src/host-scan.ts</code>, <code>packages/config/src/host-types.ts</code>, <code>packages/config/src/host.ts</code>, <code>packages/config/src/index.ts</code>, <code>packages/config/src/types.ts</code></li></ul></details><h2 id="package-summary" tabindex="-1">Package summary <a class="header-anchor" href="#package-summary" aria-label="Permalink to “Package summary”">​</a></h2><p>Canonical project configuration and defineConfig authoring surface. Re-exports the public surface of <a href="/api/core.html"><code>@pikacss/core</code></a>.</p><p>Use <a href="/getting-started/engine-config.html">Engine configuration</a> when you need conceptual usage guidance instead of exact symbol lookup.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><h3 id="function-defineconfig" tabindex="-1">defineConfig <a class="header-anchor" href="#function-defineconfig" aria-label="Permalink to “defineConfig”">​</a></h3><p>Defines one canonical PikaCSS project configuration.</p><h4 id="overload-1-defineconfig-config" tabindex="-1">Overload 1: <code>defineConfig(config)</code> <a class="header-anchor" href="#overload-1-defineconfig-config" aria-label="Permalink to “Overload 1: defineConfig(config)”">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>config</code></td><td><code>SingleProjectConfig</code></td><td>Single-entry project settings, including the Engine configuration and project-owned runtime, scan, report, and generated-state options.</td></tr></tbody></table><p><strong>Returns:</strong> <code>DefinedPikaConfig</code></p><p><strong>Remarks:</strong></p><p>The returned value is an opaque transport intended only as a config file default export. Do not inspect, spread, or mutate its runtime shape.</p><h4 id="overload-2-defineconfig-entries-options" tabindex="-1">Overload 2: <code>defineConfig(entries, options?)</code> <a class="header-anchor" href="#overload-2-defineconfig-entries-options" aria-label="Permalink to “Overload 2: defineConfig(entries, options?)”">​</a></h4><p>Defines an explicit non-empty multi-entry PikaCSS project configuration.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>entries</code></td><td><code>readonly [ MultiProjectEntryConfig, ...MultiProjectEntryConfig[] ]</code></td><td>Ordered project entries. Every explicit entry owns its callable root and logical CSS module.</td></tr><tr><td><code>options?</code></td><td><code>MultiProjectConfigOptions</code></td><td>Project-wide generated-state options shared by all entries.</td></tr></tbody></table><p><strong>Returns:</strong> <code>DefinedPikaConfig</code></p><p><strong>Remarks:</strong></p><p>Explicit multi-entry authoring remains distinct even when the array currently contains one entry; hosts must not infer single-entry CSS auto-import behavior from its length.</p><br><br><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to “Types”">​</a></h2><h3 id="interface-definedpikaconfig" tabindex="-1">DefinedPikaConfig <a class="header-anchor" href="#interface-definedpikaconfig" aria-label="Permalink to “DefinedPikaConfig”">​</a></h3><p>Opaque transport produced only by defineConfig.</p><br><br><h3 id="interface-multiprojectconfigoptions" tabindex="-1">MultiProjectConfigOptions <a class="header-anchor" href="#interface-multiprojectconfigoptions" aria-label="Permalink to “MultiProjectConfigOptions”">​</a></h3><p>Project-wide options for the explicit multi-entry authoring form.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>stateDir?</code></td><td><code>string</code></td><td>Directory shared by all entries for generated authoring state.</td><td>Host-provided default, otherwise <code>.pikacss</code>.</td></tr></tbody></table><br><br><h3 id="interface-multiprojectentryconfig" tabindex="-1">MultiProjectEntryConfig <a class="header-anchor" href="#interface-multiprojectentryconfig" aria-label="Permalink to “MultiProjectEntryConfig”">​</a></h3><p>One entry in the explicit multi-entry authoring form.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>engine?</code></td><td><code>EngineConfig</code></td><td>Engine-specific configuration for this project entry.</td><td><code>{}</code></td></tr><tr><td><code>fnName</code></td><td><code>string</code></td><td>Required compile-time callable root used by this entry&#39;s source files.</td><td>—</td></tr><tr><td><code>cssModule</code></td><td><code>string</code></td><td>Required logical CSS module exposed by this entry&#39;s runtime stylesheet.</td><td>—</td></tr><tr><td><code>transformedFormat?</code></td><td><code>&#39;string&#39; | &#39;array&#39;</code></td><td>Replacement shape emitted for the configured base callable.</td><td><code>&#39;string&#39;</code></td></tr><tr><td><code>scan?</code></td><td><code>ScanConfig</code></td><td>Source scan patterns owned by this entry.</td><td>Standard include and exclude patterns from <code>DEFAULT_SCAN_INCLUDE</code> and <code>DEFAULT_SCAN_EXCLUDE</code>.</td></tr><tr><td><code>report?</code></td><td><code>ReportConfig</code></td><td>Final production report behavior for this entry.</td><td><code>false</code></td></tr></tbody></table><br><br><h3 id="type-reportconfig" tabindex="-1">ReportConfig <a class="header-anchor" href="#type-reportconfig" aria-label="Permalink to “ReportConfig”">​</a></h3><p>Optional final production-build report configuration.</p><p><strong>Type:</strong> <code>boolean | Readonly&lt;{ output: string; }&gt;</code></p><br><br><h3 id="interface-resolvedprojectconfig" tabindex="-1">ResolvedProjectConfig <a class="header-anchor" href="#interface-resolvedprojectconfig" aria-label="Permalink to “ResolvedProjectConfig”">​</a></h3><p>Canonical project semantic state consumed by host/runtime layers.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>authoringForm</code></td><td><code>&#39;single&#39; | &#39;multi&#39;</code></td><td>Authoring form used to create this project configuration.</td><td>—</td></tr><tr><td><code>stateDir</code></td><td><code>string</code></td><td>Resolved project-wide directory for generated authoring state.</td><td>—</td></tr><tr><td><code>entries</code></td><td><code>readonly ResolvedProjectEntry[]</code></td><td>Normalized entries in their authored order.</td><td>—</td></tr></tbody></table><br><br><h3 id="interface-resolvedprojectentry" tabindex="-1">ResolvedProjectEntry <a class="header-anchor" href="#interface-resolvedprojectentry" aria-label="Permalink to “ResolvedProjectEntry”">​</a></h3><p>One normalized semantic project entry.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>engine</code></td><td><code>EngineConfig</code></td><td>Engine-specific configuration retained for this entry.</td><td>—</td></tr><tr><td><code>fnName</code></td><td><code>string</code></td><td>Validated compile-time callable root for this entry.</td><td>—</td></tr><tr><td><code>cssModule</code></td><td><code>string</code></td><td>Validated logical CSS module for this entry&#39;s runtime stylesheet.</td><td>—</td></tr><tr><td><code>transformedFormat</code></td><td><code>&#39;string&#39; | &#39;array&#39;</code></td><td>Normalized replacement shape emitted for the base callable.</td><td>—</td></tr><tr><td><code>scan</code></td><td><code>ResolvedScanConfig</code></td><td>Resolved source scan patterns for this entry.</td><td>—</td></tr><tr><td><code>report</code></td><td><code>ResolvedReportConfig</code></td><td>Normalized final production report behavior for this entry.</td><td>—</td></tr></tbody></table><br><br><h3 id="type-resolvedreportconfig" tabindex="-1">ResolvedReportConfig <a class="header-anchor" href="#type-resolvedreportconfig" aria-label="Permalink to “ResolvedReportConfig”">​</a></h3><p>Normalized report behavior; <code>false</code> disables reporting.</p><p><strong>Type:</strong> <code>false | Readonly&lt;{ output?: string; }&gt;</code></p><br><br><h3 id="interface-resolvedscanconfig" tabindex="-1">ResolvedScanConfig <a class="header-anchor" href="#interface-resolvedscanconfig" aria-label="Permalink to “ResolvedScanConfig”">​</a></h3><p>Fully normalized ordered scan pattern lists.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>include</code></td><td><code>readonly string[]</code></td><td>Resolved include patterns used to select source files for scanning.</td><td>—</td></tr><tr><td><code>exclude</code></td><td><code>readonly string[]</code></td><td>Resolved exclude patterns applied after include matching.</td><td>—</td></tr></tbody></table><br><br><h3 id="interface-scanconfig" tabindex="-1">ScanConfig <a class="header-anchor" href="#interface-scanconfig" aria-label="Permalink to “ScanConfig”">​</a></h3><p>Ordered scan patterns owned by one project entry.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>include?</code></td><td><code>string | readonly string[]</code></td><td>Source-file glob or globs to include in this entry&#39;s scan.</td><td><code>DEFAULT_SCAN_INCLUDE</code> (all supported JavaScript, TypeScript, and Vue source files)</td></tr><tr><td><code>exclude?</code></td><td><code>string | readonly string[]</code></td><td>Source-file glob or globs to exclude after include matching.</td><td><code>node_modules/**</code>, <code>dist/**</code>, <code>.git/**</code>, <code>.nuxt/**</code>, <code>.output/**</code>, and <code>coverage/**</code></td></tr></tbody></table><br><br><h3 id="interface-singleprojectconfig" tabindex="-1">SingleProjectConfig <a class="header-anchor" href="#interface-singleprojectconfig" aria-label="Permalink to “SingleProjectConfig”">​</a></h3><p>Single-entry authoring form accepted by defineConfig.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>engine?</code></td><td><code>EngineConfig</code></td><td>Engine-specific configuration for this project entry.</td><td><code>{}</code></td></tr><tr><td><code>fnName?</code></td><td><code>string</code></td><td>Compile-time callable root used by this entry&#39;s source files.</td><td><code>&#39;pika&#39;</code></td></tr><tr><td><code>cssModule?</code></td><td><code>string</code></td><td>Logical CSS module exposed by this entry&#39;s runtime stylesheet.</td><td><code>&#39;pika.css&#39;</code></td></tr><tr><td><code>transformedFormat?</code></td><td><code>&#39;string&#39; | &#39;array&#39;</code></td><td>Replacement shape emitted for the configured base callable.</td><td><code>&#39;string&#39;</code></td></tr><tr><td><code>scan?</code></td><td><code>ScanConfig</code></td><td>Source scan patterns owned by this entry.</td><td>Standard include and exclude patterns from <code>DEFAULT_SCAN_INCLUDE</code> and <code>DEFAULT_SCAN_EXCLUDE</code>.</td></tr><tr><td><code>report?</code></td><td><code>ReportConfig</code></td><td>Final production report behavior for this entry.</td><td><code>false</code></td></tr><tr><td><code>stateDir?</code></td><td><code>string</code></td><td>Project-wide directory for generated authoring state.</td><td>Host-provided default, otherwise <code>.pikacss</code>.</td></tr></tbody></table><br><br><h2 id="public-subpath-pikacss-config-host" tabindex="-1">Public subpath: <code>@pikacss/config/host</code> <a class="header-anchor" href="#public-subpath-pikacss-config-host" aria-label="Permalink to “Public subpath: @pikacss/config/host”">​</a></h2><p>Import this entry as <code>@pikacss/config/host</code>.</p><h3 id="subpath-host-interface-confighostdependencytrace" tabindex="-1">ConfigHostDependencyTrace <a class="header-anchor" href="#subpath-host-interface-confighostdependencytrace" aria-label="Permalink to “ConfigHostDependencyTrace”">​</a></h3><p>Deterministic dependency trace for one config-load candidate.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>selection</code></td><td><code>readonly ConfigHostFileDependency[]</code></td><td>Config-selection paths: all auto candidates or the exact explicit path.</td><td>—</td></tr><tr><td><code>modules</code></td><td><code>readonly ConfigHostFileDependency[]</code></td><td>Actually evaluated project-local config modules.</td><td>—</td></tr><tr><td><code>all</code></td><td><code>readonly ConfigHostFileDependency[]</code></td><td>De-duplicated selection + module dependencies.</td><td>—</td></tr></tbody></table><br><br><h3 id="subpath-host-interface-confighostfiledependency" tabindex="-1">ConfigHostFileDependency <a class="header-anchor" href="#subpath-host-interface-confighostfiledependency" aria-label="Permalink to “ConfigHostFileDependency”">​</a></h3><p>File dependency emitted by the low-level Config host.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>&#39;file&#39;</code></td><td>Dependency discriminator for filesystem-backed config inputs.</td><td>—</td></tr><tr><td><code>path</code></td><td><code>string</code></td><td>Absolute dependency path watched by the consuming host.</td><td>—</td></tr></tbody></table><br><br><h3 id="subpath-host-function-createpikascanmatcher-options" tabindex="-1">createPikaScanMatcher(options) <a class="header-anchor" href="#subpath-host-function-createpikascanmatcher-options" aria-label="Permalink to “createPikaScanMatcher(options)”">​</a></h3><p>Creates the canonical source-membership matcher for one normalized entry.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>CreatePikaScanMatcherOptions</code></td><td>Normalized scan configuration and resolved state directory.</td></tr><tr><td><code>options.scan</code></td><td><code>ResolvedScanConfig</code></td><td>Normalized absolute include/exclude scan patterns.</td></tr><tr><td><code>options.stateDir</code></td><td><code>string</code></td><td>Resolved project state directory that is always excluded.</td></tr></tbody></table><p><strong>Returns:</strong> <code>PikaScanMatcher</code></p><p><strong>Remarks:</strong></p><p>Inputs are the absolute scan patterns emitted by the Config host. The resolved state directory is excluded structurally before glob matching, even when an include pattern would otherwise match it.</p><br><br><h3 id="subpath-host-interface-createpikascanmatcheroptions" tabindex="-1">CreatePikaScanMatcherOptions <a class="header-anchor" href="#subpath-host-interface-createpikascanmatcheroptions" aria-label="Permalink to “CreatePikaScanMatcherOptions”">​</a></h3><p>Inputs for createPikaScanMatcher.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>scan</code></td><td><code>ResolvedScanConfig</code></td><td>Normalized absolute include/exclude patterns for one scan entry.</td><td>—</td></tr><tr><td><code>stateDir</code></td><td><code>string</code></td><td>Resolved project state directory, always excluded regardless of globs.</td><td>—</td></tr></tbody></table><br><br><h3 id="subpath-host-interface-loadedpikaconfig" tabindex="-1">LoadedPikaConfig <a class="header-anchor" href="#subpath-host-interface-loadedpikaconfig" aria-label="Permalink to “LoadedPikaConfig”">​</a></h3><p>Canonically loaded and normalized PikaCSS project configuration.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>projectRoot</code></td><td><code>string</code></td><td>Canonical absolute project root used for config selection and normalization.</td><td>—</td></tr><tr><td><code>selectedConfigPath</code></td><td><code>string | null</code></td><td>Selected config spelling, or <code>null</code> for the synthetic no-config default.</td><td>—</td></tr><tr><td><code>configDir</code></td><td><code>string</code></td><td>Filesystem base for authored relative config values.</td><td>—</td></tr><tr><td><code>config</code></td><td><code>ResolvedProjectConfig</code></td><td>Fully normalized project configuration returned to the host.</td><td>—</td></tr><tr><td><code>dependencies</code></td><td><code>ConfigHostDependencyTrace</code></td><td>Deterministic config-selection and evaluated-module dependency trace.</td><td>—</td></tr></tbody></table><br><br><h3 id="subpath-host-function-loadpikaconfig-options" tabindex="-1">loadPikaConfig(options) <a class="header-anchor" href="#subpath-host-function-loadpikaconfig-options" aria-label="Permalink to “loadPikaConfig(options)”">​</a></h3><p>Selects, freshly evaluates, and canonically normalizes one PikaCSS project config.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>LoadPikaConfigOptions</code></td><td>Absolute project root plus optional explicit config selection and host state-directory default.</td></tr></tbody></table><p><strong>Returns:</strong> <code>Promise&lt;LoadedPikaConfig&gt;</code></p><p><strong>Remarks:</strong></p><p>This is a low-level Node host API. It never creates Engines or owns generation/watch lifecycle. Selection and actually evaluated project-local module dependencies are returned for the caller to aggregate/watch.</p><br><br><h3 id="subpath-host-interface-loadpikaconfigoptions" tabindex="-1">LoadPikaConfigOptions <a class="header-anchor" href="#subpath-host-interface-loadpikaconfigoptions" aria-label="Permalink to “LoadPikaConfigOptions”">​</a></h3><p>Low-level config selection input.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>projectRoot</code></td><td><code>string</code></td><td>Immutable absolute project root chosen by the host.</td><td>—</td></tr><tr><td><code>config?</code></td><td><code>string</code></td><td>Closed explicit config-file selection. Omit for canonical auto-discovery.</td><td>—</td></tr><tr><td><code>defaultStateDir?</code></td><td><code>string</code></td><td>Resolved absolute host state-directory default used only when config omits stateDir.</td><td>—</td></tr></tbody></table><br><br><h3 id="subpath-host-const-pika-config-auto-candidates" tabindex="-1">PIKA_CONFIG_AUTO_CANDIDATES <a class="header-anchor" href="#subpath-host-const-pika-config-auto-candidates" aria-label="Permalink to “PIKA_CONFIG_AUTO_CANDIDATES”">​</a></h3><p>Canonical config filenames checked, in order, during automatic project-config discovery.</p><br><br><h3 id="subpath-host-class-pikaconfighosterror" tabindex="-1">PikaConfigHostError <a class="header-anchor" href="#subpath-host-class-pikaconfighosterror" aria-label="Permalink to “PikaConfigHostError”">​</a></h3><p>Error from Config-host selection, evaluation, or normalization.</p><p><strong>Constructors:</strong></p><h4 id="subpath-host-class-pikaconfighosterror-constructor-options" tabindex="-1">constructor(options) <a class="header-anchor" href="#subpath-host-class-pikaconfighosterror-constructor-options" aria-label="Permalink to “constructor(options)”">​</a></h4><p>Creates an error carrying the failed config-host operation and its dependency trace.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>{ message: string; projectRoot: string; selectedConfigPath?: string | null; dependencies: ConfigHostDependencyTrace; cause?: unknown; }</code></td><td>Failed operation details and the dependencies observed before it failed.</td><td>—</td></tr><tr><td><code>options.message</code></td><td><code>string</code></td><td>Human-readable description of the config-host failure.</td><td>—</td></tr><tr><td><code>options.projectRoot</code></td><td><code>string</code></td><td>Absolute project root used for config selection.</td><td>—</td></tr><tr><td><code>options.selectedConfigPath?</code></td><td><code>string | null</code></td><td>Selected config path, or <code>null</code> when no config was selected.</td><td><code>null</code></td></tr><tr><td><code>options.dependencies</code></td><td><code>ConfigHostDependencyTrace</code></td><td>Config-selection and evaluated-module dependencies observed before the failure.</td><td>—</td></tr><tr><td><code>options.cause?</code></td><td><code>unknown</code></td><td>Underlying error, when one caused the failure.</td><td>—</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>projectRoot</code></td><td><code>string</code></td><td>Project root associated with the failed host operation.</td><td>—</td></tr><tr><td><code>selectedConfigPath</code></td><td><code>string | null</code></td><td>Selected config path when known, otherwise <code>null</code>.</td><td>—</td></tr><tr><td><code>dependencies</code></td><td><code>ConfigHostDependencyTrace</code></td><td>Dependency trace accumulated before the host operation failed.</td><td>—</td></tr></tbody></table><br><br><h3 id="subpath-host-interface-pikascanmatcher" tabindex="-1">PikaScanMatcher <a class="header-anchor" href="#subpath-host-interface-pikascanmatcher" aria-label="Permalink to “PikaScanMatcher”">​</a></h3><p>Efficient matcher for one normalized entry scan.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>matches</code></td><td><code>(filePath: string) =&gt; boolean</code></td><td>Returns whether one absolute physical source path belongs to the entry.</td><td>—</td></tr></tbody></table><br><br><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/getting-started/engine-config.html">Engine configuration</a></li><li><a href="/api/integration.html">Integration API reference</a></li><li><a href="/api/">API reference overview</a></li></ul>`,135)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};